Result<void> revalidate_qt_equity_desk_accounting(pqxx::work& tx,const J& d,const std::string& id){try{auto p=preview(tx,d);admit(tx,d,p.at("payload").at("selection_rows"),id,true);capture_authority(tx,d,p);return Result<void>();}catch(const std::exception&){return make_error<void>(ErrorCode::INVALID_DATA,"qt_equity_accounting_input_changed","qt_equity_desk_accounting");}}
