    need(publication.at("attempt_id")==receipt.at("attempt_id")&&publication.at("preview_payload_digest")==p.at("payload_digest")&&publication.at("published_book_digest")==receipt.at("published_book_digest")&&receipt.at("published_book_digest")==d.at("selected_book_digest")&&publication.at("observation_id")==observed.at("observation_id")&&publication.at("observation_digest")==observed.at("content_digest")&&publication.at("before_accounting")==p.at("read_set_payload").at("saved_accounting"));
    auto timing=tx.exec("SELECT i.as_of=o.as_of AND i.valid_until=o.valid_until AND i.as_of<=r.processed_at AND r.processed_at<=i.valid_until FROM trading.qt_desk_accounting_inputs i JOIN trading.qt_execution_observations o ON o.observation_id=i.input_id JOIN trading.qt_desk_receipts r ON r.decision_id=i.decision_id WHERE i.input_id="+tx.quote(id)+"::uuid");need(timing.size()==1&&!timing[0][0].is_null()&&timing[0][0].as<bool>());
    J original_positions=J::array(),selected=J::array();for(const auto& f:out.at("observation").at("fills")){original_positions.push_back({{"key",f.at("key")},{"quantity_exact",f.at("selected_quantity_exact")},{"average_price_exact",f.at("average_price_exact")},{"daily_realized_pnl_exact",f.at("daily_realized_pnl_exact")},{"daily_unrealized_pnl_exact",f.at("daily_unrealized_pnl_exact")},{"last_update",f.at("last_update")}});selected.push_back({{"key",f.at("key")},{"quantity_exact",f.at("selected_quantity_exact")}});}
    need(sorted(original_positions)==sorted(publication.at("after_accounting")));auto selected_digest=qt_digest_v1(J{{"selection_rows",selected}});need(selected_digest.is_ok()&&selected_digest.value()==text(d.at("selected_book_digest")));
    auto desk_result=one(tx,"SELECT to_jsonb(r) FROM trading.qt_desk_results r WHERE decision_id="+tx.quote(text(d.at("decision_id")))+"::uuid FOR SHARE");
    need(desk_result.at("attempt_id")==receipt.at("attempt_id")&&desk_result.at("observation_id")==observed.at("observation_id")&&desk_result.at("content_digest")==publication.at("results_digest")&&hash(desk_result.at("payload"))==text(desk_result.at("content_digest")));
    const auto& rp=desk_result.at("payload");shape(rp,{"schema_version","decision_id","observation_id","book_id","source_day","selected_book_digest","results"});need(rp.at("schema_version")=="qt-desk-result/v1"&&rp.at("observation_id")==observed.at("observation_id")&&rp.at("results")==out.at("observation").at("results"));for(auto f:{"decision_id","book_id","source_day","selected_book_digest"})need(rp.at(f)==d.at(f));
    const auto& snapshot=p.at("read_set_payload");auto read_bytes=canonical_qt_desk_read_set_bytes(snapshot);need(read_bytes.is_ok());auto read_hash=qt_sha256_hex(read_bytes.value());need(read_hash.is_ok()&&read_hash.value()==text(d.at("read_set_digest")));auto loaded_model=load_qt_model_publication_record(tx,text(d.at("model_publication_id")));need(loaded_model.is_ok());const auto& model=loaded_model.value().row;need(model.at("portfolio_id")==d.at("book_id")&&model.at("source_day")==d.at("source_day"));
    const auto& ref=loaded_model.value().reference;size_t matches=0;for(const auto& r:snapshot.at("publication_refs"))if(r.at("publication_id")==model.at("publication_id")){need(r==ref);++matches;}need(matches==1);
    J system=J::array();for(const auto& r:snapshot.at("system_rows"))if(r.at("key").at("strategy_id")==model.at("strategy_id"))system.push_back(r);
    const auto& seed=model.at("system_components");
    const bool empty_owner=loaded_model.value().kind==QtModelPublicationKind::EmptyOwnerV2;
    need(seed.is_array()&&(empty_owner?seed.empty():!seed.empty())&&seed.size()<=4096&&sorted(seed)==sorted(system));
    if(out.at("schema_version")=="qt-equity-accounting-empty-owner/v2"){
        need(empty_owner&&evaluation_snapshot.at("payload").at("schema_version")=="qt-inputs-empty-owner/v2");
        require_empty_model(tx,d,p.at("payload").at("selection_rows"));
        for(auto f:{"system_rows","source_rows","saved_rows","saved_accounting"})need(snapshot.at(f).is_array()&&snapshot.at(f).empty());
    }
    if(empty_owner)need(snapshot.at("system_rows").empty());
    for(const auto& r:seed){shape(r,{"key","quantity_exact","average_price_exact"});const auto& k=r.at("key");need(k.at("portfolio_id")==d.at("book_id")&&k.at("date")==d.at("source_day")&&k.at("portfolio_type")=="system"&&k.at("strategy_id")==model.at("strategy_id"));}
    auto seed_digest=qt_digest_v1(J{{"seed_rows",seed}});need(seed_digest.is_ok()&&seed_digest.value()==text(model.at("seed_digest")));
    auto manifest=qt_validate_proposal_manifest_json(model.at("proposal_components"),text(d.at("book_id")),text(model.at("strategy_id")),text(d.at("source_day")));need(manifest.is_ok()&&hash(manifest.value())==text(model.at("proposal_manifest_digest")));
    const auto& provenance=snapshot.at("provenance");need(provenance.at("status")=="ready"&&provenance.at("seed_digest")==model.at("seed_digest")&&provenance.at("source_digest")==p.at("source_digest")&&provenance.at("chain_digest")==p.at("provenance_digest"));
    const auto& evaluator=snapshot.at("evaluator");need(evaluator.at("status")=="available"&&evaluator.at("build")==p.at("evaluator_build")&&evaluator.at("policy_version")==p.at("policy_version"));
    const auto& capability=snapshot.at("capability");need(capability.at("status")=="present"&&capability.at("enabled")==true&&capability.at("version")==d.at("workflow_capability_version"));
    matches=0;for(const auto& grant:snapshot.at("grants"))if(grant.at("user_id")==std::to_string(d.at("created_by").get<int64_t>())&&grant.at("capability")=="qt_submit"){need(grant.at("active")==true&&grant.at("version")==d.at("submitter_grant_version"));++matches;}need(matches==1);
    auto prior=one(tx,"SELECT to_jsonb(f) FROM trading.qt_desk_finalization_sources f WHERE source_id="+tx.quote(text(input.at("payload").at("prior_finalization_source_id")))+" FOR SHARE");
    if(prior.at("payload").at("schema_version")=="qt-equity-finalized-accounting/v1")prior_physical(tx,d,prior.at("payload"),out.at("schema_version")=="qt-equity-accounting-empty-owner/v2");
    return J{{"decision",d},{"preview",p},{"input",input},{"output",result},{"observed",observed},{"receipt",receipt},{"desk_result",desk_result},{"model",model},{"prior",prior},{"market",original_market},{"evaluation_snapshot",evaluation_snapshot},{"decoded_sources",decoded_sources}};
