Result<void> verify_qt_equity_desk_original_outputs(pqxx::work& tx,const J& d,const std::string& id){auto records=load_qt_equity_desk_original_records(tx,d,id);if(records.is_error())return make_error<void>(ErrorCode::INVALID_DATA,"qt_equity_original_proof_unavailable","qt_equity_desk_accounting");return validate_qt_equity_original_lineage(tx,records.value());}
Result<void> verify_qt_equity_desk_accounting_outputs(pqxx::work& tx,const J& d,const std::string& id){try{
    auto records=load_qt_equity_desk_original_records(tx,d,id);need(records.is_ok());const auto& out=records.value().at("output").at("payload");
    auto successor=verified_qt_equity_desk_finalization(tx,d);need(successor.is_ok());
    J expected_positions=J::array(),expected_live,expected_curve;
    if(successor.value().is_null()){
        for(const auto& f:out.at("observation").at("fills"))expected_positions.push_back({{"key",f.at("key")},{"quantity_exact",f.at("selected_quantity_exact")},{"average_price_exact",f.at("average_price_exact")},{"daily_realized_pnl_exact",f.at("daily_realized_pnl_exact")},{"daily_unrealized_pnl_exact",f.at("daily_unrealized_pnl_exact")},{"last_update",f.at("last_update")}});
        expected_live=out.at("live_results");expected_curve=out.at("equity_curve");
    }else{expected_positions=successor.value().at("positions");expected_live=successor.value().at("live_results");expected_curve=successor.value().at("equity_curve");}
    for(auto& r:expected_live)r.erase("initial_capital_exact");
    need(sorted(positions(tx,d,text(d.at("source_day"))))==sorted(expected_positions)&&sorted(live(tx,d,text(d.at("source_day"))))==sorted(expected_live)&&sorted(curves(tx,d,text(d.at("source_day"))))==sorted(expected_curve));
    auto actual=executions(tx,d);for(auto& e:actual){need(e.at("_partial")==false);e.erase("_partial");}need(sorted(actual)==sorted(out.at("executions")));return Result<void>();
}catch(const std::exception&){return make_error<void>(ErrorCode::INVALID_DATA,"qt_equity_accounting_outputs_changed","qt_equity_desk_accounting");}}
Result<void> store_qt_equity_desk_accounting(pqxx::work& tx,const J& d,const std::string& id,const J& out){try{
    need(out.at("schema_version")=="qt-equity-accounting/v1"||out.at("schema_version")=="qt-equity-accounting-empty-owner/v2");
    for(const auto& r:out.at("live_results")){const auto day=text(r.at("date")),engine=text(r.at("strategy_id"));need(r.at("portfolio_id")==d.at("book_id")&&r.at("date")==d.at("source_day")&&r.at("portfolio_type")=="qt");const auto date=live_date(tx,day);const auto engine_scope="portfolio_id="+tx.quote(text(d.at("book_id")))+" AND strategy_id="+tx.quote(engine)+" AND portfolio_type='qt'";tx.exec("DELETE FROM trading.executions WHERE "+engine_scope+" AND date="+tx.quote(day)+"::date");tx.exec("DELETE FROM trading.live_results WHERE "+engine_scope+" AND "+date.day+"="+tx.quote(day));
        std::string values=tx.quote(text(d.at("book_id")))+","+tx.quote(engine)+","+date.value+",'qt'";
        for(auto f:{"daily_pnl_exact","daily_realized_pnl_exact","daily_unrealized_pnl_exact","daily_transaction_costs_exact","total_realized_pnl_exact","total_unrealized_pnl_exact","total_transaction_costs_exact","total_pnl_exact","current_portfolio_value_exact"})values+=","+tx.quote(text(r.at(f)));
        tx.exec("INSERT INTO trading.live_results(portfolio_id,strategy_id,date,portfolio_type,daily_pnl,daily_realized_pnl,daily_unrealized_pnl,daily_transaction_costs,total_realized_pnl,total_unrealized_pnl,total_transaction_costs,total_pnl,current_portfolio_value) VALUES("+values+")");
    }
    for(const auto& r:out.at("equity_curve"))tx.exec("INSERT INTO trading.equity_curve(portfolio_id,strategy_id,timestamp,portfolio_type,equity) VALUES("+tx.quote(text(r.at("portfolio_id")))+","+tx.quote(text(r.at("strategy_id")))+","+tx.quote(text(r.at("timestamp")))+"::timestamptz,'qt',"+tx.quote(text(r.at("equity_exact")))+") ON CONFLICT(portfolio_id,strategy_id,timestamp,portfolio_type) DO UPDATE SET equity=EXCLUDED.equity");
    for(const auto& r:out.at("executions")){const auto& k=r.at("key");std::string values;for(auto f:{"portfolio_id","strategy_id","strategy_name","date","symbol","portfolio_type"}){if(!values.empty())values+=",";values+=tx.quote(text(k.at(f)));}for(auto f:{"exec_id","order_id","side","quantity_exact","price_exact","execution_time","commissions_fees_exact","implicit_price_impact_exact","slippage_market_impact_exact","total_transaction_costs_exact"})values+=","+tx.quote(text(r.at(f)));tx.exec("INSERT INTO trading.executions(portfolio_id,strategy_id,strategy_name,date,symbol,portfolio_type,exec_id,order_id,side,quantity,price,execution_time,commissions_fees,implicit_price_impact,slippage_market_impact,total_transaction_costs,is_partial) VALUES("+values+",false)");}
    tx.exec("INSERT INTO trading.desk_run_results(decision_id,input_id,portfolio_id,date,content_digest,payload) VALUES("+tx.quote(text(d.at("decision_id")))+"::uuid,"+tx.quote(id)+"::uuid,"+tx.quote(text(d.at("book_id")))+","+tx.quote(text(d.at("source_day")))+"::date,"+tx.quote(hash(out,true))+","+tx.quote(out.dump())+"::jsonb)");return Result<void>();
}catch(const std::exception&){return make_error<void>(ErrorCode::INVALID_DATA,"qt_equity_accounting_storage_failed","qt_equity_desk_accounting");}}
Result<void> assemble_qt_equity_desk_accounting_input(pqxx::work& tx,const J& d,const J& selection,const std::string& id,const std::string& market_id,const std::string& final_id){try{
    auto market=one(tx,"SELECT to_jsonb(m) FROM trading.qt_desk_market_sources m WHERE source_id="+tx.quote(market_id)+"::uuid FOR SHARE");auto final=one(tx,"SELECT to_jsonb(f) FROM trading.qt_desk_finalization_sources f WHERE source_id="+tx.quote(final_id)+" FOR SHARE");auto in=reconstructed(tx,d,selection,id,market,final);
    tx.exec("INSERT INTO trading.qt_desk_accounting_inputs(input_id,decision_id,producer_id,policy_version,source_version,as_of,valid_until,content_digest,payload) SELECT "+tx.quote(id)+"::uuid,"+tx.quote(text(d.at("decision_id")))+"::uuid,producer_id,policy_version,"+tx.quote("qt-input/"+id)+",as_of,valid_until,"+tx.quote(hash(in))+","+tx.quote(in.dump())+"::jsonb FROM trading.qt_desk_market_sources WHERE source_id="+tx.quote(market_id)+"::uuid");admit(tx,d,selection,id,true);return Result<void>();
}catch(const std::exception&){return make_error<void>(ErrorCode::INVALID_DATA,"qt_equity_upstream_input_unavailable","qt_equity_desk_accounting");}}
